func testOrcamentoSituacaoToManyAddOpOrOrcamentoCompras(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a OrcamentoSituacao
	var b, c, d, e OrcamentoCompra

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, orcamentoSituacaoDBTypes, false, strmangle.SetComplement(orcamentoSituacaoPrimaryKeyColumns, orcamentoSituacaoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*OrcamentoCompra{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, orcamentoCompraDBTypes, false, strmangle.SetComplement(orcamentoCompraPrimaryKeyColumns, orcamentoCompraColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*OrcamentoCompra{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddOrOrcamentoCompras(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.OrsID != first.OrsID {
			t.Error("foreign key was wrong value", a.OrsID, first.OrsID)
		}
		if a.OrsID != second.OrsID {
			t.Error("foreign key was wrong value", a.OrsID, second.OrsID)
		}

		if first.R.Or != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Or != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.OrOrcamentoCompras[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.OrOrcamentoCompras[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.OrOrcamentoCompras().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

